from transformers.models.qwen3.modeling_qwen3 import Qwen3DecoderLayer, Qwen3RMSNorm, Qwen3RotaryEmbedding
rot=Qwen3RotaryEmbedding(config).to('mps')
class Tail(torch.nn.Module):
    def __init__(s):
        super().__init__()
        s.layers=torch.nn.ModuleList([Qwen3DecoderLayer(config,i) for i in [26,27]])
        s.norm=Qwen3RMSNorm(config.hidden_size,eps=config.rms_norm_eps)
        s.lm=torch.nn.Linear(1024,config.vocab_size,bias=False)
    def forward(s,h):
        T=h.shape[1]; pos=torch.arange(T,device=h.device)[None]
        pe=rot(h,pos)
        mask=torch.full((T,T),float('-inf'),device=h.device).triu(1)[None,None].to(h.dtype)
        for l in s.layers: 
            o=l(h,attention_mask=mask,position_embeddings=pe,position_ids=pos)
            h=o[0] if isinstance(o,tuple) else o
        return s.lm(s.norm(h))[:,-1]
